// UI clicks (tabs, home chips, logout). Kept separate from data changes via area='click'.
var _clickLast = '', _clickAt = 0;
window.logClick = function (action, details) {
  var now = Date.now();
  var key = String(action || '') + '|' + String(details || '');
  if (key === _clickLast && (now - _clickAt) < 600) return; // debounce double-fires
  _clickLast = key; _clickAt = now;
  window.logChange('click', action, details);
};

