// ═══════════════════════════════════════════════════════════════════════════════
// 🕘 CHANGE LOG (v11) — per-account audit trail (server-stamped usernames).
// Saves, file uploads/deletes, Property Info edits and blocked wipes are logged
// automatically on the server; the client adds a few explicit events.
// ═══════════════════════════════════════════════════════════════════════════════
(function () {
  'use strict';
  let _rows = [], _f = { user: '', area: '' }, _busy = false;
  const _esc = function (s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
  const AREA_COL = { data: 'var(--tx2)', files: '#7c5cbf', pinfo: '#C9A84C', app: 'var(--tx3)' };
  window.logFilter = function (k, v) { _f[k] = v; renderLog(); };
  window.renderLog = async function () {
    const p = document.getElementById('tab-log');
    if (!p) return;
    if (!_busy) {
      _busy = true;
      try {
        const q = new URLSearchParams({ limit: '400' });
        if (_f.user) q.set('user', _f.user);
        if (_f.area) q.set('area', _f.area);
        const r = await fetch('/api/changelog?' + q.toString());
        _rows = r.ok ? await r.json() : [];
      } catch (e) { _rows = []; }
      _busy = false;
    }
    const users = Array.from(new Set(_rows.map(function (r) { return r.username; }).filter(Boolean))).sort();
    const areas = Array.from(new Set(_rows.map(function (r) { return r.area; }).filter(Boolean))).sort();
    const opt = function (list, cur) { return '<option value="">all</option>' + list.map(function (v) { return '<option value="' + _esc(v) + '"' + (v === cur ? ' selected' : '') + '>' + _esc(v) + '</option>'; }).join(''); };
    const rowsH = _rows.map(function (r) {
      const d = new Date(r.ts);
      const when = isNaN(d) ? '' : d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }) + ' ' + d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
      return '<tr style="border-bottom:1px solid var(--bdr)">' +
        '<td style="padding:6px 10px;font-family:var(--mono);font-size:11px;color:var(--tx3);white-space:nowrap">' + when + '</td>' +
        '<td style="padding:6px 10px;font-size:12px;font-weight:600;color:#C9A84C;white-space:nowrap">👤 ' + _esc(r.username) + '</td>' +
        '<td style="padding:6px 10px;font-size:11px;font-weight:600;color:' + (AREA_COL[r.area] || 'var(--tx2)') + ';white-space:nowrap">' + _esc(r.area) + '</td>' +
        '<td style="padding:6px 10px;font-size:12px;color:var(--tx);white-space:nowrap">' + _esc(r.action) + '</td>' +
        '<td style="padding:6px 10px;font-size:11.5px;color:var(--tx2)">' + _esc(r.details) + '</td></tr>';
    }).join('');
    p.innerHTML = '<div style="padding:18px 22px;max-width:1240px;margin:0 auto">' +
      '<div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:10px">' +
      '<h2 style="margin:0;font-size:20px;color:var(--tx)">🕘 Change Log</h2>' +
      '<label style="font-size:12px;color:var(--tx3)">user <select onchange="logFilter(\'user\',this.value)" style="font-size:12px;padding:4px 8px;border:1px solid var(--bdr);border-radius:6px;background:var(--bg);color:var(--tx)">' + opt(users, _f.user) + '</select></label>' +
      '<label style="font-size:12px;color:var(--tx3)">area <select onchange="logFilter(\'area\',this.value)" style="font-size:12px;padding:4px 8px;border:1px solid var(--bdr);border-radius:6px;background:var(--bg);color:var(--tx)">' + opt(areas, _f.area) + '</select></label>' +
      '<button class="btn sm" onclick="renderLog()">⟳ Refresh</button></div>' +
      '<div style="font-size:11.5px;color:var(--tx3);margin-bottom:10px">Every save is recorded with who made it and what changed at a glance (e.g. “bks 812→814 · payChk ✎”). File uploads, Property Info edits and blocked wipe attempts are captured automatically. Newest first, last 8&#8239;000 entries kept.</div>' +
      '<div class="card" style="padding:0;overflow:auto"><table style="border-collapse:collapse;width:100%;min-width:760px">' +
      '<tr><th style="text-align:left;padding:7px 10px;font-size:10.5px;color:var(--tx3);text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid var(--bdr2)">When</th>' +
      '<th style="text-align:left;padding:7px 10px;font-size:10.5px;color:var(--tx3);text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid var(--bdr2)">Who</th>' +
      '<th style="text-align:left;padding:7px 10px;font-size:10.5px;color:var(--tx3);text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid var(--bdr2)">Area</th>' +
      '<th style="text-align:left;padding:7px 10px;font-size:10.5px;color:var(--tx3);text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid var(--bdr2)">Action</th>' +
      '<th style="text-align:left;padding:7px 10px;font-size:10.5px;color:var(--tx3);text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid var(--bdr2)">What changed</th></tr>' +
      (rowsH || '<tr><td colspan="5" style="padding:22px;text-align:center;color:var(--tx3)">No entries yet — they will appear as the team works.</td></tr>') +
      '</table></div></div>';
  };
})();

