      '<div class="card" style="padding:0;overflow:auto"><table style="border-collapse:collapse;width:100%;min-width:860px">' +
      '<tr><th style="text-align:left;padding:7px 10px;font-size:10.5px;color:var(--tx3);text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid var(--bdr2)">When</th>' +
